-- Store real per-locale copy instead of duplicating Traditional Chinese into every editor field.
-- Official romanized stage names remain unchanged in every language.
update public.site_content
set value = value
  || jsonb_build_object(
    'storyLead.zh-TW', coalesce(nullif(value->>'storyLead', ''), '七位成員把 vocal、rap、dance 與強烈舞台能量凝聚成 BABYMONSTER。'),
    'storyBody.zh-TW', coalesce(nullif(value->>'storyBody', ''), 'BABYMONSTER 是 YG Entertainment 推出的七人女子團體，由 RUKA、PHARITA、ASA、AHYEON、RAMI、RORA、CHIQUITA 組成。她們於 2024 年以《BABYMONS7ER》正式出道，持續以多元作品與現場演出拓展全球舞台。'),
    'groupDetail.zh-TW', coalesce(value->>'groupDetail', ''),
    'member.ruka.bio.zh-TW', coalesce(value->>'member.ruka.bio', ''),
    'member.ruka.detail.zh-TW', coalesce(value->>'member.ruka.detail', ''),
    'member.pharita.bio.zh-TW', coalesce(value->>'member.pharita.bio', ''),
    'member.pharita.detail.zh-TW', coalesce(value->>'member.pharita.detail', ''),
    'member.asa.bio.zh-TW', coalesce(value->>'member.asa.bio', ''),
    'member.asa.detail.zh-TW', coalesce(value->>'member.asa.detail', ''),
    'member.ahyeon.bio.zh-TW', coalesce(value->>'member.ahyeon.bio', ''),
    'member.ahyeon.detail.zh-TW', coalesce(value->>'member.ahyeon.detail', ''),
    'member.rami.bio.zh-TW', coalesce(value->>'member.rami.bio', ''),
    'member.rami.detail.zh-TW', coalesce(value->>'member.rami.detail', ''),
    'member.rora.bio.zh-TW', coalesce(value->>'member.rora.bio', ''),
    'member.rora.detail.zh-TW', coalesce(value->>'member.rora.detail', ''),
    'member.chiquita.bio.zh-TW', coalesce(value->>'member.chiquita.bio', ''),
    'member.chiquita.detail.zh-TW', coalesce(value->>'member.chiquita.detail', '')
  )
  || $translations$
  {
    "storyLead.zh-CN": "七位成员将 vocal、rap、dance 与强烈舞台能量凝聚成 BABYMONSTER。",
    "storyLead.th": "สมาชิกทั้งเจ็ดผสานเสียงร้อง แร็ป การเต้น และพลังบนเวทีอันโดดเด่นให้เป็น BABYMONSTER",
    "storyLead.en": "Seven members unite vocals, rap, dance, and fearless stage energy as BABYMONSTER.",
    "storyLead.ko": "일곱 멤버의 보컬, 랩, 댄스와 강렬한 무대 에너지가 BABYMONSTER를 완성합니다.",
    "storyLead.ja": "7人のボーカル、ラップ、ダンス、そして力強いステージエネルギーがBABYMONSTERを形作ります。",
    "storyBody.zh-CN": "BABYMONSTER 是 YG Entertainment 推出的七人女子组合，由 RUKA、PHARITA、ASA、AHYEON、RAMI、RORA 与 CHIQUITA 组成。她们于 2024 年通过《BABYMONS7ER》正式出道，并持续以多样化作品和现场演出拓展全球舞台。",
    "storyBody.th": "BABYMONSTER คือเกิร์ลกรุ๊ป 7 คนจาก YG Entertainment ประกอบด้วย RUKA, PHARITA, ASA, AHYEON, RAMI, RORA และ CHIQUITA วงเดบิวต์อย่างเป็นทางการในปี 2024 ด้วย BABYMONS7ER และขยายเวทีระดับโลกอย่างต่อเนื่องผ่านผลงานที่หลากหลายและการแสดงสด",
    "storyBody.en": "BABYMONSTER is a seven-member girl group from YG Entertainment consisting of RUKA, PHARITA, ASA, AHYEON, RAMI, RORA, and CHIQUITA. They officially debuted with BABYMONS7ER in 2024 and continue expanding their global stage through diverse releases and live performances.",
    "storyBody.ko": "BABYMONSTER는 YG Entertainment의 7인조 걸그룹으로 RUKA, PHARITA, ASA, AHYEON, RAMI, RORA, CHIQUITA로 구성됩니다. 2024년 BABYMONS7ER로 공식 데뷔했으며 다양한 작품과 라이브 무대를 통해 글로벌 활동을 넓혀 가고 있습니다.",
    "storyBody.ja": "BABYMONSTERはYG Entertainmentの7人組ガールズグループで、RUKA、PHARITA、ASA、AHYEON、RAMI、RORA、CHIQUITAで構成されています。2024年に『BABYMONS7ER』で正式デビューし、多彩な作品とライブパフォーマンスを通してグローバルな舞台を広げています。",
    "groupDetail.zh-CN": "BABYMONSTER（베이비몬스터）是韩国 YG Entertainment 推出的七人女子组合，由 RUKA、PHARITA、ASA、AHYEON、RAMI、RORA 与 CHIQUITA 组成。成员来自韩国、日本和泰国。YG 将 2024 年 4 月 1 日定为团体正式出道日；当天七位成员共同发行首张迷你专辑《BABYMONS7ER》。\n\n团名结合了“BABY”的年轻与成长潜力，以及“MONSTER”所代表的强大实力和舞台爆发力。七位成员并非被限制在单一分工中，而是共同展现歌唱、说唱、舞蹈与现场表演能力。她们的音乐以 YG 擅长的 Hip-Hop 为基础，同时融入 R&B、Pop、Dance Pop 与抒情元素。\n\n团体在正式出道前推出《BATTER UP》和《Stuck In The Middle》，之后通过《SHEESH》《FOREVER》《DRIP》等作品扩展音乐风格。成员的多国籍背景和语言能力，也让 BABYMONSTER 从成立之初就具有全球活动方向。官方粉丝名 MONSTIEZ 结合“MON'S”与“TIES”，象征 BABYMONSTER 与粉丝之间紧密而相互支持的连结。最新作品、成员活动与巡演信息请以 YG Entertainment 及 BABYMONSTER 官方平台为准。",
    "groupDetail.th": "BABYMONSTER (베이비몬스터) คือเกิร์ลกรุ๊ป 7 คนจาก YG Entertainment ประกอบด้วย RUKA, PHARITA, ASA, AHYEON, RAMI, RORA และ CHIQUITA สมาชิกมาจากเกาหลีใต้ ญี่ปุ่น และไทย โดย YG กำหนดให้วันที่ 1 เมษายน 2024 ซึ่งทั้งเจ็ดคนออกมินิอัลบั้มแรก BABYMONS7ER เป็นวันเดบิวต์อย่างเป็นทางการ\n\nชื่อวงผสานความอ่อนเยาว์และศักยภาพในการเติบโตของคำว่า “BABY” เข้ากับความสามารถและพลังบนเวทีระดับ “MONSTER” สมาชิกไม่ได้ถูกจำกัดไว้เพียงบทบาทเดียว แต่ร่วมกันแสดงทักษะด้านการร้อง แร็ป เต้น และการแสดงสด ดนตรีของวงมีฮิปฮอปแบบ YG เป็นแกนหลัก พร้อมผสม R&B, Pop, Dance Pop และเพลงที่เน้นเสียงร้อง\n\nก่อนเดบิวต์อย่างเป็นทางการ วงได้เผยแพร่ BATTER UP และ Stuck In The Middle ก่อนขยายสีสันทางดนตรีผ่าน SHEESH, FOREVER และ DRIP ภูมิหลังหลากหลายสัญชาติและภาษาของสมาชิกทำให้ BABYMONSTER มีทิศทางระดับโลกตั้งแต่เริ่มต้น ชื่อแฟนคลับอย่างเป็นทางการ MONSTIEZ ผสานคำว่า “MON'S” กับ “TIES” เพื่อสื่อถึงสายสัมพันธ์และการสนับสนุนระหว่างวงกับแฟน ๆ โปรดตรวจสอบผลงาน กิจกรรมสมาชิก และตารางทัวร์ล่าสุดจาก YG Entertainment และช่องทางทางการของ BABYMONSTER",
    "groupDetail.en": "BABYMONSTER (베이비몬스터) is a seven-member girl group from YG Entertainment, consisting of RUKA, PHARITA, ASA, AHYEON, RAMI, RORA, and CHIQUITA. The members come from South Korea, Japan, and Thailand. YG recognizes April 1, 2024—the release date of the seven-member debut mini album BABYMONS7ER—as the group's official debut.\n\nThe name combines the youth and growth potential suggested by “BABY” with the exceptional skill and stage power represented by “MONSTER.” Rather than being confined to one role, the members collectively demonstrate vocals, rap, dance, and live-performance ability. Their music is rooted in YG-style hip-hop while also drawing on R&B, pop, dance-pop, and vocal-focused material.\n\nBefore the official debut, the group released BATTER UP and Stuck In The Middle, then broadened its musical identity through releases including SHEESH, FOREVER, and DRIP. The members' multinational backgrounds and language skills have supported a global direction from the beginning. Their official fandom name, MONSTIEZ, combines “MON'S” and “TIES” to represent the close, mutually supportive bond between BABYMONSTER and its fans. For the latest releases, member activities, and tour information, refer to YG Entertainment and BABYMONSTER's official channels.",
    "groupDetail.ko": "BABYMONSTER(베이비몬스터)는 YG Entertainment가 선보인 7인조 걸그룹으로, RUKA·PHARITA·ASA·AHYEON·RAMI·RORA·CHIQUITA로 구성되어 있습니다. 멤버들은 한국, 일본, 태국 출신입니다. YG는 일곱 멤버가 첫 미니 앨범 BABYMONS7ER를 함께 발표한 2024년 4월 1일을 공식 데뷔일로 안내합니다.\n\n팀명은 ‘BABY’가 뜻하는 젊음과 성장 가능성, 그리고 ‘MONSTER’가 상징하는 뛰어난 실력과 무대 에너지를 결합한 이름입니다. 멤버들은 하나의 역할에만 한정되지 않고 보컬, 랩, 댄스와 라이브 퍼포먼스를 함께 보여 줍니다. 음악은 YG 특유의 힙합을 바탕으로 R&B, 팝, 댄스 팝과 보컬 중심의 곡까지 폭넓게 아우릅니다.\n\n정식 데뷔 전 BATTER UP과 Stuck In The Middle을 공개했으며, 이후 SHEESH, FOREVER, DRIP 등의 작품으로 음악적 색깔을 확장했습니다. 다국적 구성과 언어적 배경은 데뷔 초기부터 글로벌 활동의 기반이 되었습니다. 공식 팬덤명 MONSTIEZ는 ‘MON'S’와 ‘TIES’를 결합해 BABYMONSTER와 팬들이 서로 의지하고 긴밀히 연결된 관계를 의미합니다. 최신 음반, 멤버 활동과 투어 정보는 YG Entertainment 및 BABYMONSTER 공식 채널에서 확인해 주세요.",
    "groupDetail.ja": "BABYMONSTER（ベイビーモンスター）は、YG Entertainmentからデビューした7人組ガールズグループで、RUKA、PHARITA、ASA、AHYEON、RAMI、RORA、CHIQUITAで構成されています。メンバーの出身は韓国、日本、タイです。YGは、7人で初のミニアルバム『BABYMONS7ER』を発表した2024年4月1日を公式デビュー日としています。\n\nグループ名は、「BABY」が表す若さと成長の可能性に、「MONSTER」が象徴する高い実力とステージでの爆発力を組み合わせたものです。メンバーは一つの役割だけに限定されず、ボーカル、ラップ、ダンス、ライブパフォーマンスを総合的に披露します。音楽はYGらしいHip-Hopを軸に、R&B、Pop、Dance Pop、歌声を生かした楽曲まで幅広く展開しています。\n\n正式デビュー前にBATTER UPとStuck In The Middleを発表し、その後はSHEESH、FOREVER、DRIPなどを通して音楽性を広げてきました。多国籍な構成と言語的背景も、当初からグローバルに活動する土台となっています。公式ファンダム名のMONSTIEZは「MON'S」と「TIES」を組み合わせ、BABYMONSTERとファンが支え合う強い結びつきを表します。最新の作品、メンバー活動、ツアー情報はYG EntertainmentおよびBABYMONSTER公式チャンネルをご確認ください。",

    "member.ruka.bio.zh-CN": "沉稳与爆发力兼备，RUKA 以流畅舞蹈、说唱和鲜明的舞台魅力展现独特存在感。",
    "member.ruka.bio.th": "RUKA ผสานความนิ่งกับพลังอันโดดเด่น ผ่านการเต้นที่ลื่นไหล แร็ป และเสน่ห์บนเวทีที่ชัดเจน",
    "member.ruka.bio.en": "RUKA balances composure and power through fluid dance, rap, and a distinctive stage presence.",
    "member.ruka.bio.ko": "RUKA는 안정감과 폭발력을 겸비한 춤, 랩과 선명한 무대 장악력으로 자신만의 존재감을 보여 줍니다.",
    "member.ruka.bio.ja": "RUKAは落ち着きと力強さを兼ね備え、滑らかなダンス、ラップ、鮮やかなステージで独自の存在感を放ちます。",
    "member.ruka.detail.zh-CN": "RUKA 出生于 2002 年 3 月 20 日，是 BABYMONSTER 年龄最大的成员，也是两位日本成员之一。加入 YG 前，她已经累积多年舞蹈经验；长期训练让她形成成熟、稳定且富有控制力的表演风格。\n\n她擅长以身体节奏诠释 Hip-Hop，在力量、流畅度与音乐感之间取得平衡，并把对节奏的敏感延伸到说唱。与舞台上的强烈气场相比，私下的 RUKA 更放松而风趣。舞蹈既是她的工作，也是释放压力和获得快乐的重要方式。",
    "member.ruka.detail.th": "RUKA เกิดวันที่ 20 มีนาคม 2002 เป็นสมาชิกที่อายุมากที่สุดของ BABYMONSTER และเป็นหนึ่งในสมาชิกชาวญี่ปุ่นสองคน เธอสั่งสมประสบการณ์การเต้นมาหลายปีก่อนเข้า YG และการฝึกฝนอย่างต่อเนื่องทำให้การแสดงของเธอมีวุฒิภาวะ มั่นคง และควบคุมร่างกายได้ดี\n\nเธอโดดเด่นในการถ่ายทอดจังหวะฮิปฮอปผ่านร่างกาย โดยรักษาสมดุลระหว่างพลัง ความลื่นไหล และความเป็นดนตรี ความไวต่อจังหวะยังต่อยอดไปสู่การแร็ป นอกเวที RUKA มีมุมที่ผ่อนคลายและสนุกสนาน การเต้นเป็นทั้งงานและวิธีที่เธอใช้ปลดปล่อยความเครียดและค้นหาความสุข",
    "member.ruka.detail.en": "Born on March 20, 2002, RUKA is BABYMONSTER's eldest member and one of its two Japanese members. She had already accumulated years of dance experience before joining YG, and sustained training shaped a mature, steady, and controlled performance style.\n\nShe is especially skilled at expressing hip-hop rhythm through movement, balancing power, fluidity, and musicality. That rhythmic awareness also carries into her rap. Away from her commanding stage image, RUKA is known for a relaxed and playful side; dance is both her profession and an important source of release and joy.",
    "member.ruka.detail.ko": "RUKA는 2002년 3월 20일생으로 BABYMONSTER의 맏언니이자 두 명의 일본인 멤버 중 한 명입니다. YG에 들어오기 전부터 오랫동안 춤을 배웠고, 꾸준한 훈련을 통해 성숙하고 안정적이며 절제된 퍼포먼스 스타일을 완성했습니다.\n\n힙합의 리듬을 몸으로 표현하는 능력이 뛰어나며 힘, 유연한 흐름과 음악성 사이의 균형을 잘 잡습니다. 이러한 리듬 감각은 랩에서도 드러납니다. 강렬한 무대 이미지와 달리 평소에는 편안하고 유쾌한 모습을 보이며, 춤은 일인 동시에 스트레스를 풀고 즐거움을 얻는 중요한 방법입니다.",
    "member.ruka.detail.ja": "RUKAは2002年3月20日生まれで、BABYMONSTERの最年長メンバーであり、2人いる日本人メンバーの一人です。YGに入る前から長年のダンス経験を積み、継続的なトレーニングによって、成熟した安定感と高いコントロール力を備えたスタイルを築きました。\n\nHip-Hopのリズムを身体で表現することに優れ、力強さ、滑らかさ、音楽性のバランスを取ります。そのリズム感はラップにも生かされています。強いステージイメージとは対照的に、普段はリラックスしたユーモラスな一面もあり、ダンスは仕事であると同時に、心を解放し喜びを得る大切な方法です。",

    "member.pharita.bio.zh-CN": "来自泰国的 PHARITA 以清澈歌声、稳定演唱和优雅气质展现独有魅力。",
    "member.pharita.bio.th": "PHARITA สมาชิกชาวไทย ถ่ายทอดเสน่ห์เฉพาะตัวผ่านน้ำเสียงใส การร้องที่มั่นคง และบุคลิกสง่างาม",
    "member.pharita.bio.en": "Thailand's PHARITA stands out through her clear voice, steady delivery, and elegant presence.",
    "member.pharita.bio.ko": "태국 출신 PHARITA는 맑은 음색, 안정적인 보컬과 우아한 분위기로 자신만의 매력을 보여 줍니다.",
    "member.pharita.bio.ja": "タイ出身のPHARITAは、澄んだ歌声、安定した歌唱、上品な雰囲気で独自の魅力を見せます。",
    "member.pharita.detail.zh-CN": "PHARITA 出生于 2005 年 8 月 26 日，是 BABYMONSTER 的泰国成员之一。她从众多竞争者中脱颖而出进入 YG，并前往韩国接受练习生训练。国际学校背景使她能自然使用英语，也有助于海外访问与全球活动。\n\n她的魅力来自干净、优雅而耐看的气质。无论是柔和歌曲还是充满力量的 Hip-Hop 作品，她都能保留清晰的声线和从容的舞台表现。她曾受到 BLACKPINK LISA 的启发踏上 K-pop 道路，也为 BABYMONSTER 的声音与形象增添细腻而柔和的层次。",
    "member.pharita.detail.th": "PHARITA เกิดวันที่ 26 สิงหาคม 2005 เป็นหนึ่งในสมาชิกชาวไทยของ BABYMONSTER เธอผ่านการแข่งขันจำนวนมากเพื่อเข้าเป็นเด็กฝึกของ YG และย้ายไปเกาหลีใต้เพื่อฝึกฝน พื้นฐานจากโรงเรียนนานาชาติทำให้เธอสื่อสารภาษาอังกฤษได้อย่างเป็นธรรมชาติ และช่วยในการสัมภาษณ์กับกิจกรรมระดับโลก\n\nเสน่ห์ของเธออยู่ที่ความสะอาด สง่างาม และน่าจดจำ ไม่ว่าจะเป็นเพลงอ่อนโยนหรือผลงานฮิปฮอปที่ทรงพลัง เธอยังคงรักษาสีเสียงที่ชัดเจนและท่าทีบนเวทีที่สุขุม PHARITA ได้รับแรงบันดาลใจจาก LISA แห่ง BLACKPINK ให้เดินบนเส้นทาง K-pop และเพิ่มมิติที่ละเอียดอ่อนให้กับเสียงและภาพลักษณ์ของ BABYMONSTER",
    "member.pharita.detail.en": "Born on August 26, 2005, PHARITA is one of BABYMONSTER's Thai members. She earned a place at YG through a highly competitive selection and moved to South Korea for training. Her international-school background enables natural English communication in overseas interviews and global activities.\n\nHer appeal is clean, elegant, and quietly memorable. Whether performing a gentle song or a forceful hip-hop track, she retains a clear vocal identity and composed stage manner. Inspired in part by BLACKPINK's LISA to pursue K-pop, PHARITA adds a refined and softer dimension to BABYMONSTER's sound and image.",
    "member.pharita.detail.ko": "PHARITA는 2005년 8월 26일생으로 BABYMONSTER의 태국인 멤버 중 한 명입니다. 치열한 경쟁을 거쳐 YG 연습생으로 선발되어 한국에서 훈련했으며, 국제학교 경험을 바탕으로 영어로도 자연스럽게 소통해 해외 인터뷰와 글로벌 활동에서 강점을 보입니다.\n\n깨끗하고 우아하며 은은하게 기억에 남는 분위기가 특징입니다. 부드러운 곡과 강한 힙합 곡 모두에서 선명한 음색과 여유 있는 무대 태도를 유지합니다. BLACKPINK 리사의 영향을 받아 K-pop의 길을 꿈꾼 PHARITA는 BABYMONSTER의 사운드와 이미지에 섬세하고 부드러운 결을 더합니다.",
    "member.pharita.detail.ja": "PHARITAは2005年8月26日生まれで、BABYMONSTERのタイ人メンバーの一人です。多くの候補者の中からYGの練習生に選ばれ、韓国でトレーニングを重ねました。インターナショナルスクールで学んだ経験から英語で自然に会話でき、海外インタビューやグローバル活動でも強みを発揮します。\n\n清潔感のある上品な雰囲気と、静かに印象を残す存在感が魅力です。柔らかな楽曲でも力強いHip-Hopでも、澄んだ声の個性と落ち着いたステージ表現を保ちます。BLACKPINKのLISAに影響を受けてK-popを志したPHARITAは、BABYMONSTERのサウンドとイメージに繊細で柔らかな層を加えています。",

    "member.asa.bio.zh-CN": "精准快速的说唱、出色节奏感与创作能力，让 ASA 成为 BABYMONSTER 极具辨识度的成员。",
    "member.asa.bio.th": "แร็ปที่แม่นยำและรวดเร็ว จังหวะอันโดดเด่น และความสามารถด้านการสร้างสรรค์ ทำให้ ASA มีเอกลักษณ์ชัดเจนใน BABYMONSTER",
    "member.asa.bio.en": "ASA's precise rapid-fire rap, strong rhythm, and creative instinct make her one of BABYMONSTER's most distinctive members.",
    "member.asa.bio.ko": "정확하고 빠른 랩, 뛰어난 리듬 감각과 창작 역량은 ASA를 BABYMONSTER에서 가장 뚜렷한 개성을 지닌 멤버 중 한 명으로 만듭니다.",
    "member.asa.bio.ja": "正確で速いラップ、優れたリズム感と創作力によって、ASAはBABYMONSTERの中でも際立つ個性を見せます。",
    "member.asa.detail.zh-CN": "ASA 出生于 2006 年 4 月 17 日，是 BABYMONSTER 的日本成员之一。即使韩语并非母语，她在发音、节奏控制与高速说唱方面仍展现很高的完成度。\n\n她不仅演绎已有的说唱段落，也对歌词、Flow 和音乐制作抱有浓厚兴趣。练习生时期便曾表演自己创作的说唱，并持续从生活中寻找创作灵感。舞台上的锐利感与生活中细心、有条理的一面形成鲜明反差。",
    "member.asa.detail.th": "ASA เกิดวันที่ 17 เมษายน 2006 เป็นหนึ่งในสมาชิกชาวญี่ปุ่นของ BABYMONSTER แม้ภาษาเกาหลีไม่ใช่ภาษาแม่ แต่เธอแสดงความแม่นยำสูงทั้งการออกเสียง การควบคุมจังหวะ และการแร็ปความเร็วสูง\n\nเธอไม่ได้เพียงถ่ายทอดท่อนแร็ปที่มีอยู่ แต่ยังสนใจการเขียนเนื้อ Flow และการทำเพลง ตั้งแต่ช่วงเป็นเด็กฝึก เธอเคยแสดงแร็ปที่แต่งเองและยังคงหาแรงบันดาลใจจากชีวิตรอบตัว ความเฉียบคมบนเวทีตัดกับบุคลิกที่ละเอียดและเป็นระเบียบในชีวิตประจำวันอย่างชัดเจน",
    "member.asa.detail.en": "Born on April 17, 2006, ASA is one of BABYMONSTER's Japanese members. Although Korean is not her first language, she demonstrates a high level of pronunciation, rhythmic control, and rapid rap delivery.\n\nShe is interested not only in performing written parts but also in lyrics, flow, and music production. During her trainee period she performed self-written rap and has continued to draw creative ideas from everyday life. Her sharp stage character contrasts with an attentive and highly organized personality away from the spotlight.",
    "member.asa.detail.ko": "ASA는 2006년 4월 17일생으로 BABYMONSTER의 일본인 멤버 중 한 명입니다. 한국어가 모국어가 아님에도 발음, 리듬 조절과 빠른 랩에서 높은 완성도를 보여 줍니다.\n\n주어진 랩을 소화하는 데 그치지 않고 가사, 플로와 음악 제작에도 깊은 관심을 가지고 있습니다. 연습생 시절부터 직접 쓴 랩을 선보였으며 일상에서 창작의 영감을 찾습니다. 무대 위의 날카로운 이미지와 평소의 세심하고 정돈된 성격이 뚜렷한 대비를 이룹니다.",
    "member.asa.detail.ja": "ASAは2006年4月17日生まれで、BABYMONSTERの日本人メンバーの一人です。韓国語が母語ではないにもかかわらず、発音、リズムのコントロール、高速ラップで高い完成度を見せます。\n\n用意されたパートをこなすだけでなく、歌詞、フロウ、音楽制作にも強い関心を持っています。練習生時代から自作ラップを披露し、日常から創作のヒントを探してきました。ステージ上の鋭さと、普段の細やかで整理上手な性格との対比も魅力です。",

    "member.ahyeon.bio.zh-CN": "从高音、说唱到舞蹈都展现强大实力，AHYEON 以全面能力与爆发力成为舞台焦点。",
    "member.ahyeon.bio.th": "ตั้งแต่เสียงสูง แร็ป ไปจนถึงการเต้น AHYEON โดดเด่นด้วยความสามารถรอบด้านและพลังที่ดึงสายตาบนเวที",
    "member.ahyeon.bio.en": "From high notes and rap to dance, AHYEON's all-round ability and explosive power make her a commanding stage focus.",
    "member.ahyeon.bio.ko": "고음과 랩부터 댄스까지 강한 역량을 보여 주는 AHYEON은 다재다능함과 폭발적인 에너지로 무대의 중심을 잡습니다.",
    "member.ahyeon.bio.ja": "高音、ラップ、ダンスまで高い実力を見せるAHYEONは、オールラウンドな能力と爆発力でステージの視線を集めます。",
    "member.ahyeon.detail.zh-CN": "AHYEON 出生于 2007 年 4 月 11 日，是 BABYMONSTER 的韩国成员。她能同时处理歌唱、说唱与舞蹈，并以具有穿透力的高音和强烈舞台能量著称。她并非只依赖高音，在节奏、表情与不同歌曲风格之间的转换也很有辨识度。\n\n正式出道前，她翻唱 Charlie Puth《Dangerously》的表演已获得广泛关注。她也具备韩语、英语和中文能力。舞台上的爆发力与私下喜欢绘画、听音乐的安静兴趣形成反差，展现出表演者之外的艺术感。",
    "member.ahyeon.detail.th": "AHYEON เกิดวันที่ 11 เมษายน 2007 เป็นสมาชิกชาวเกาหลีใต้ของ BABYMONSTER เธอทำได้ทั้งร้อง แร็ป และเต้น พร้อมเป็นที่รู้จักจากเสียงสูงที่ทะลุชัดและพลังบนเวที อย่างไรก็ตาม ความโดดเด่นของเธอไม่ได้อยู่ที่เสียงสูงเท่านั้น แต่ยังรวมถึงจังหวะ สีหน้า และการสลับบทบาทในเพลงหลากหลายแนว\n\nก่อนเดบิวต์ การคัฟเวอร์เพลง Dangerously ของ Charlie Puth ได้รับความสนใจอย่างกว้างขวาง เธอยังสื่อสารภาษาเกาหลี อังกฤษ และจีนได้ พลังอันเข้มข้นบนเวทีตัดกับความสนใจที่เงียบสงบอย่างการวาดภาพและฟังเพลง เผยให้เห็นมุมศิลปินนอกเหนือจากการแสดง",
    "member.ahyeon.detail.en": "Born on April 11, 2007, AHYEON is a South Korean member of BABYMONSTER. She performs across vocals, rap, and dance, and is recognized for penetrating high notes and intense stage energy. Her identity is not limited to high notes: rhythm, facial expression, and the ability to shift roles across different styles are equally important.\n\nBefore debut, her cover of Charlie Puth's Dangerously attracted wide attention. She can also communicate in Korean, English, and Chinese. Her explosive performance image contrasts with quieter interests such as drawing and listening to music, revealing an artistic side beyond the stage.",
    "member.ahyeon.detail.ko": "AHYEON은 2007년 4월 11일생인 BABYMONSTER의 한국인 멤버입니다. 보컬, 랩과 댄스를 모두 소화하며 뚜렷하게 뻗는 고음과 강한 무대 에너지로 주목받습니다. 고음에만 의존하지 않고 리듬, 표정과 다양한 장르에서 역할을 전환하는 능력도 높은 개성을 만듭니다.\n\n데뷔 전 Charlie Puth의 Dangerously 커버로 널리 주목받았으며 한국어, 영어와 중국어로 소통할 수 있습니다. 무대 위 폭발적인 모습과 달리 그림 그리기와 음악 감상 같은 차분한 취미를 즐겨, 퍼포머 너머의 예술적인 면모도 보여 줍니다.",
    "member.ahyeon.detail.ja": "AHYEONは2007年4月11日生まれの韓国人メンバーです。ボーカル、ラップ、ダンスをこなし、突き抜ける高音と強いステージエネルギーで知られています。高音だけに頼らず、リズム、表情、さまざまなスタイルで役割を切り替える力も大きな個性です。\n\nデビュー前にはCharlie PuthのDangerouslyをカバーした映像が広く注目されました。韓国語、英語、中国語でもコミュニケーションできます。ステージ上の爆発力とは対照的に、絵を描くことや音楽を聴くことを好む静かな一面があり、パフォーマンス以外の芸術性も感じさせます。",

    "member.rami.bio.zh-CN": "从低音到高音都富有魅力，RAMI 以细腻音色、转音技巧与宽广音域展现强大演唱实力。",
    "member.rami.bio.th": "ตั้งแต่เสียงต่ำถึงเสียงสูง RAMI แสดงพลังการร้องผ่านสีเสียงละเอียด เทคนิคการเอื้อน และช่วงเสียงกว้าง",
    "member.rami.bio.en": "Across low and high registers, RAMI displays vocal strength through nuanced tone, agile runs, and a wide range.",
    "member.rami.bio.ko": "RAMI는 저음부터 고음까지 섬세한 음색, 유연한 애드리브와 넓은 음역으로 강한 보컬 역량을 보여 줍니다.",
    "member.rami.bio.ja": "低音から高音まで、RAMIは繊細な音色、自在なフェイク、広い音域で高いボーカル力を発揮します。",
    "member.rami.detail.zh-CN": "RAMI 出生于 2007 年 10 月 17 日，是 BABYMONSTER 的韩国成员。她小时候曾从事儿童模特儿工作，2018 年进入 YG 后，通过多年训练逐渐建立自己的歌唱风格。\n\n她的优势是声音的弹性：既能处理细腻温暖的低音，也能延伸至具有爆发力的高音，并自然加入转音与 Vocal Run。她喜欢学习新的歌唱、舞蹈和乐器技巧，也擅长根据节拍即兴发展旋律，是持续探索声音可能性的表演者。",
    "member.rami.detail.th": "RAMI เกิดวันที่ 17 ตุลาคม 2007 เป็นสมาชิกชาวเกาหลีใต้ของ BABYMONSTER เธอเคยทำงานเป็นนางแบบเด็ก และหลังเข้า YG ในปี 2018 ก็พัฒนารูปแบบการร้องของตนเองผ่านการฝึกฝนหลายปี\n\nจุดแข็งของเธอคือความยืดหยุ่นของเสียง เธอทำได้ทั้งเสียงต่ำที่ละเอียดและอบอุ่น รวมถึงเสียงสูงที่ทรงพลัง พร้อมเติมการเอื้อนและ Vocal Run อย่างเป็นธรรมชาติ RAMI สนุกกับการเรียนรู้การร้อง เต้น และเครื่องดนตรีใหม่ ๆ อีกทั้งยังสามารถด้นทำนองจากบีต จึงเป็นนักแสดงที่สำรวจความเป็นไปได้ของเสียงอยู่เสมอ",
    "member.rami.detail.en": "Born on October 17, 2007, RAMI is a South Korean member of BABYMONSTER. She worked as a child model when young and, after joining YG in 2018, developed her individual vocal style through years of training.\n\nHer greatest strength is flexibility: she can shape nuanced, warm low notes and extend into powerful highs, adding natural runs and ornamentation along the way. She enjoys learning new vocal, dance, and instrumental skills and can improvise melodies over a beat, making her a performer who continually explores the possibilities of her voice.",
    "member.rami.detail.ko": "RAMI는 2007년 10월 17일생인 BABYMONSTER의 한국인 멤버입니다. 어린 시절 아동 모델로 활동했고 2018년 YG에 들어온 뒤 오랜 훈련을 거치며 자신만의 보컬 스타일을 발전시켰습니다.\n\n가장 큰 강점은 목소리의 유연함입니다. 섬세하고 따뜻한 저음부터 힘 있는 고음까지 소화하며 자연스러운 기교와 보컬 런을 더합니다. 새로운 노래, 춤과 악기 기술을 배우는 것을 좋아하고 비트 위에서 멜로디를 즉흥적으로 만드는 능력도 있어, 목소리의 가능성을 계속 탐구하는 퍼포머입니다.",
    "member.rami.detail.ja": "RAMIは2007年10月17日生まれの韓国人メンバーです。幼い頃に子役モデルを経験し、2018年にYGへ入ってから長年のトレーニングを通して自分らしいボーカルスタイルを育てました。\n\n最大の強みは声の柔軟性です。繊細で温かい低音から力強い高音まで扱い、自然なフェイクやVocal Runを加えます。歌、ダンス、楽器の新しい技術を学ぶことが好きで、ビートに合わせて即興でメロディーを作る力もあり、声の可能性を探求し続けるパフォーマーです。",

    "member.rora.bio.zh-CN": "成熟沉稳的音色配合自然表达力，让 RORA 在歌声、舞台与谈吐中拥有独特存在感。",
    "member.rora.bio.th": "สีเสียงที่สุขุมเกินวัยและการถ่ายทอดอย่างเป็นธรรมชาติ ทำให้ RORA มีเอกลักษณ์ทั้งในการร้อง เวที และการสื่อสาร",
    "member.rora.bio.en": "RORA's mature, grounded tone and natural expressiveness give her a distinct presence in singing, performance, and conversation.",
    "member.rora.bio.ko": "성숙하고 안정적인 음색과 자연스러운 표현력은 RORA가 노래, 무대와 대화에서 고유한 존재감을 갖게 합니다.",
    "member.rora.bio.ja": "成熟した落ち着きのある音色と自然な表現力によって、RORAは歌、ステージ、言葉のすべてで独自の存在感を見せます。",
    "member.rora.detail.zh-CN": "RORA 出生于 2008 年 8 月 14 日，是 BABYMONSTER 的韩国成员。她虽然年纪较小，却拥有厚实、柔和而富有深度的声线，擅长通过音色与情绪逐步建立歌曲氛围。\n\n这份沉稳也体现在表达方式上。她能清楚说明自己的想法，并在团体访问中自然传达 BABYMONSTER 的特色。成为 YG 练习生前，她曾有儿童团体活动经验。私下喜欢绘画、看戏剧与料理，少女般自然的一面与舞台上的成熟感形成独特反差。",
    "member.rora.detail.th": "RORA เกิดวันที่ 14 สิงหาคม 2008 เป็นสมาชิกชาวเกาหลีใต้ของ BABYMONSTER แม้อายุยังน้อย แต่เธอมีน้ำเสียงที่หนา นุ่ม และลุ่มลึก โดยสร้างบรรยากาศของเพลงผ่านสีเสียงและอารมณ์อย่างค่อยเป็นค่อยไป\n\nความสุขุมนี้ยังปรากฏในการสื่อสาร เธออธิบายความคิดได้ชัดเจนและถ่ายทอดเอกลักษณ์ของ BABYMONSTER ในบทสัมภาษณ์ได้อย่างเป็นธรรมชาติ ก่อนเป็นเด็กฝึก YG เธอเคยมีประสบการณ์ในวงเด็ก นอกเวทีเธอชอบวาดภาพ ดูละคร และทำอาหาร ความเป็นธรรมชาติแบบวัยรุ่นตัดกับวุฒิภาวะบนเวทีอย่างมีเสน่ห์",
    "member.rora.detail.en": "Born on August 14, 2008, RORA is a South Korean member of BABYMONSTER. Despite her young age, she has a full, soft, and deep vocal color, building a song's atmosphere gradually through tone and emotion.\n\nThat composure also appears in how she communicates. She explains her thoughts clearly and naturally conveys BABYMONSTER's identity in group interviews. Before becoming a YG trainee, she had experience in a children's group. Away from the stage she enjoys drawing, watching dramas, and cooking, creating an appealing contrast between youthful ease and onstage maturity.",
    "member.rora.detail.ko": "RORA는 2008년 8월 14일생인 BABYMONSTER의 한국인 멤버입니다. 어린 나이에도 두텁고 부드러우며 깊이 있는 음색을 지녔고, 목소리와 감정으로 곡의 분위기를 차분히 쌓는 데 강점이 있습니다.\n\n이러한 안정감은 말할 때도 드러납니다. 자신의 생각을 명확히 설명하며 단체 인터뷰에서 BABYMONSTER의 특징을 자연스럽게 전달합니다. YG 연습생이 되기 전에는 키즈 그룹 활동 경험이 있습니다. 평소에는 그림, 드라마 감상과 요리를 좋아하며 소녀다운 자연스러움과 무대 위 성숙함이 매력적인 대비를 이룹니다.",
    "member.rora.detail.ja": "RORAは2008年8月14日生まれの韓国人メンバーです。年齢は若いものの、厚みがあり柔らかく深い声を持ち、音色と感情によって楽曲の空気をゆっくり築くことを得意とします。\n\nその落ち着きは話し方にも表れます。自分の考えを明確に説明し、グループインタビューではBABYMONSTERの特徴を自然に伝えます。YGの練習生になる前にはキッズグループで活動した経験があります。普段は絵、ドラマ鑑賞、料理を好み、少女らしい自然さとステージ上の成熟した姿が魅力的な対比を生みます。",

    "member.chiquita.bio.zh-CN": "明亮活泼而富有感染力，CHIQUITA 以丰富表情、歌声与舞台爆发力展现忙内魅力。",
    "member.chiquita.bio.th": "CHIQUITA สดใส เป็นธรรมชาติ และเปี่ยมพลัง ถ่ายทอดเสน่ห์ของน้องเล็กผ่านสีหน้า เสียงร้อง และพลังบนเวที",
    "member.chiquita.bio.en": "Bright, lively, and infectious, CHIQUITA expresses her maknae charm through vivid expression, vocals, and explosive stage energy.",
    "member.chiquita.bio.ko": "밝고 활기차며 강한 전염력을 지닌 CHIQUITA는 풍부한 표정, 보컬과 무대 에너지로 막내의 매력을 보여 줍니다.",
    "member.chiquita.bio.ja": "明るく生き生きとしたCHIQUITAは、豊かな表情、歌声、爆発的なステージエネルギーで末っ子らしい魅力を見せます。",
    "member.chiquita.detail.zh-CN": "CHIQUITA 出生于 2009 年 2 月 17 日，来自泰国，是 BABYMONSTER 年龄最小的成员。尽管年纪最小，她在舞台上的自信与表现力十分突出，善于通过表情、眼神和肢体传达歌曲情绪。\n\n她可以在强势概念中迅速切换为锐利表情，也能在轻松内容中展现明亮活力。和 PHARITA 一样，她深受 BLACKPINK LISA 启发。私下喜欢跳舞、与家人聊天和创作数位艺术。她不只是可爱的忙内，也是拥有舞台本能与成长潜力的年轻表演者。",
    "member.chiquita.detail.th": "CHIQUITA เกิดวันที่ 17 กุมภาพันธ์ 2009 มาจากประเทศไทย และเป็นสมาชิกที่อายุน้อยที่สุดของ BABYMONSTER แม้จะเป็นน้องเล็ก แต่ความมั่นใจและการแสดงออกบนเวทีโดดเด่นมาก เธอสื่ออารมณ์ของเพลงผ่านสีหน้า สายตา และการเคลื่อนไหวได้อย่างเป็นธรรมชาติ\n\nเธอเปลี่ยนเป็นสีหน้าคมเข้มได้รวดเร็วในคอนเซปต์ที่ทรงพลัง และแสดงพลังสดใสในเนื้อหาที่ผ่อนคลาย เช่นเดียวกับ PHARITA เธอได้รับแรงบันดาลใจจาก LISA แห่ง BLACKPINK นอกตารางงาน เธอชอบเต้น พูดคุยกับครอบครัว และสร้างงานศิลปะดิจิทัล CHIQUITA จึงไม่ใช่เพียงน้องเล็กที่น่ารัก แต่เป็นนักแสดงรุ่นเยาว์ที่มีสัญชาตญาณบนเวทีและศักยภาพในการเติบโต",
    "member.chiquita.detail.en": "Born on February 17, 2009, CHIQUITA is from Thailand and is BABYMONSTER's youngest member. Despite being the youngest, her confidence and expressive power stand out on stage. She communicates a song's emotion naturally through facial expression, eye contact, and movement.\n\nShe can switch quickly to a sharp expression for a forceful concept, then show bright energy in lighter content. Like PHARITA, she was strongly inspired by BLACKPINK's LISA. Away from schedules, she enjoys dancing, talking with family, and creating digital art. CHIQUITA is therefore more than a charming maknae: she is a young performer with stage instinct and considerable room to grow.",
    "member.chiquita.detail.ko": "CHIQUITA는 2009년 2월 17일생으로 태국 출신이며 BABYMONSTER의 막내입니다. 가장 어린 멤버이지만 무대 위 자신감과 표현력이 뛰어나 표정, 시선과 몸짓으로 곡의 감정을 자연스럽게 전달합니다.\n\n강한 콘셉트에서는 날카로운 표정으로 빠르게 전환하고, 편안한 콘텐츠에서는 밝은 에너지를 보여 줍니다. PHARITA와 마찬가지로 BLACKPINK 리사에게 큰 영감을 받았습니다. 평소에는 춤, 가족과의 대화와 디지털 아트를 즐깁니다. CHIQUITA는 귀여운 막내를 넘어 무대 본능과 큰 성장 가능성을 지닌 젊은 퍼포머입니다.",
    "member.chiquita.detail.ja": "CHIQUITAは2009年2月17日生まれのタイ出身で、BABYMONSTERの最年少メンバーです。末っ子ながらステージでの自信と表現力が際立ち、表情、視線、身体の動きで楽曲の感情を自然に伝えます。\n\n強いコンセプトでは鋭い表情へ素早く切り替え、リラックスしたコンテンツでは明るいエネルギーを見せます。PHARITAと同じくBLACKPINKのLISAから大きな影響を受けました。普段はダンス、家族との会話、デジタルアートを楽しみます。CHIQUITAは愛らしい末っ子であるだけでなく、ステージの本能と大きな成長性を持つ若いパフォーマーです。"
  }
